INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Desktop-PC immer leistungsstärker als ein Notebook?', 2, '[{"text": "Nein", "correct": true, "because": "High-End-Notebooks können mithalten"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Komponente ist für einen Desktop-PC unverzichtbar?', 3, '[{"text": "Mainboard", "correct": true, "because": "Verbindet alle Teile"}, {"text": "Monitor", "correct": false, "because": "Optional bei Servernutzung"}, {"text": "Maus", "correct": false, "because": "Nur Eingabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat ein Desktop-PC?', 5, '[{"text": "Aufrüstbarkeit", "correct": true, "because": "Einfacher Hardwaretausch"}, {"text": "Hohe Leistung", "correct": true, "because": "Platz für starke Komponenten"}, {"text": "Portabilität", "correct": false, "because": "Nicht mobil"}, {"text": "Geringer Stromverbrauch", "correct": false, "because": "Höher als bei Laptops"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Desktop-PCs sind modular. b) Sie brauchen immer eine GPU.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Integrierte Grafik reicht oft"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Auswahl eines Desktop-PCs fürs Büro?', 4, '[{"text": "Prozessorleistung", "correct": false, "because": "Wichtig für Aufgaben"}, {"text": "RAM-Kapazität", "correct": false, "because": "Beeinflusst Multitasking"}, {"text": "RGB-Beleuchtung", "correct": true, "because": "Rein ästhetisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Desktop-PC ohne Netzteil läuft?', 2, '[{"text": "Nein", "correct": true, "because": "Stromversorgung essenziell"}, {"text": "Ja", "correct": false, "because": "Ohne PSU kein Betrieb"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt das Netzteil bei einem Desktop-PC?', 3, '[{"text": "Versorgt Komponenten mit Strom", "correct": true, "because": "Kernfunktion des PSU"}, {"text": "Kühlt die CPU", "correct": false, "because": "Das machen Lüfter"}, {"text": "Erhöht die Taktfrequenz", "correct": false, "because": "Nicht Aufgabe des Netzteils"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Teile machen einen Desktop-PC leistungsstark?', 5, '[{"text": "CPU", "correct": true, "because": "Rechenleistung"}, {"text": "SSD", "correct": true, "because": "Schneller Datenzugriff"}, {"text": "Webcam", "correct": false, "because": "Nur Zusatz"}, {"text": "Lautsprecher", "correct": false, "because": "Nur Ausgabe"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Desktop-PCs sind für Server geeignet. b) Sie sind immer teurer als Laptops. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Preis variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht zwingend für einen Desktop-PC?', 4, '[{"text": "Mainboard", "correct": false, "because": "Grundkomponente"}, {"text": "RAM", "correct": false, "because": "Arbeitsspeicher nötig"}, {"text": "Externe Tastatur", "correct": true, "because": "Alternative Eingaben möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Sind Desktop-PCs nur für Spiele gedacht?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für Arbeit und Server"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften machen einen Desktop-PC anpassbar?', 4, '[{"text": "PCIe-Steckplätze", "correct": true, "because": "Für Erweiterungen"}, {"text": "Großes Gehäuse", "correct": true, "because": "Platz für Komponenten"}, {"text": "Leichtbauweise", "correct": false, "because": "Nicht mobil"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass ein Desktop-PC ohne Netzwerk nutzlos ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Lokale Nutzung möglich"}, {"text": "Ja", "correct": false, "because": "Netzwerk nicht zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Zusammenstellung eines Desktop-PCs?', 3, '[{"text": "Kompatibilität", "correct": true, "because": "Sichert Funktion"}, {"text": "Niedriger Preis", "correct": false, "because": "Qualität wichtiger"}, {"text": "Optisches Design", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Desktop-PCs haben mehr Kühloptionen. b) Sie sind immer lauter als Laptops.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Lautstärke variiert"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Features sind für einen Arbeits-PC wichtig?', 5, '[{"text": "Schnelle SSD", "correct": true, "because": "Beschleunigt Zugriff"}, {"text": "Ausreichend RAM", "correct": true, "because": "Für Multitasking"}, {"text": "Integrierte Kamera", "correct": false, "because": "Nicht essenziell"}, {"text": "Bunte LEDs", "correct": false, "because": "Nur Deko"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Desktop-PC unwichtig?', 3, '[{"text": "Kühlung", "correct": false, "because": "Schützt Hardware"}, {"text": "Netzteil", "correct": false, "because": "Stromversorgung nötig"}, {"text": "Tragbarkeit", "correct": true, "because": "Stationär genutzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Braucht ein Desktop-PC immer eine separate Grafikkarte?', 3, '[{"text": "Nein", "correct": true, "because": "Integrierte Grafik oft ausreichend"}, {"text": "Ja", "correct": false, "because": "Abhängig vom Einsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Desktop-PC als Server dienen kann?', 2, '[{"text": "Ja", "correct": true, "because": "Mit passender Konfig möglich"}, {"text": "Nein", "correct": false, "because": "Nicht nur für Clients"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Feature macht einen Desktop-PC langlebig?', 4, '[{"text": "Erweiterbarkeit", "correct": true, "because": "Anpassung an neue Technik"}, {"text": "Kompakte Bauweise", "correct": false, "because": "Eher bei Laptops"}, {"text": "Geringes Gewicht", "correct": false, "because": "Nicht relevant"}]');
